WITH cleaned AS (SELECT id, order_id, method, amount, TO_DATE(paid_at) paid_at_date, FLOOR(amount) amount_whole, COALESCE(method, 'UNKNOWN') method_filled FROM payments WHERE order_id IS NOT NULL) SELECT id, amount, amount_whole, method_filled, LAG(amount) OVER (PARTITION BY method, order_id ORDER BY amount ASC, id ASC) prev_amount, LEAD(amount_whole) OVER (PARTITION BY method, order_id ORDER BY amount ASC, id ASC) next_amount_whole, LAG(amount_whole) OVER (PARTITION BY method, order_id ORDER BY amount ASC, id ASC) prev_amount_whole, ROW_NUMBER() OVER (PARTITION BY method, order_id ORDER BY amount ASC, id ASC) seq_no FROM cleaned
